using System;
using System.Text;
using Newtonsoft.Json.Linq;
namespace RoomLab.Native
{
    // Shared .NET/Unity contract checks for editor 2.5.5 additions absent from old oracle.
    public static class NativeGameplaySmokeChecks
    {
        public static int Run(NativeProject source)
        {
            int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new Exception("Gameplay contract: "+why);}
            NativeMotion Fixture(JArray objects,NativeGameplayRules rules=NativeGameplayRules.Editor255Compat){var raw=(JObject)source.NormalizedJson.DeepClone();var c=(JObject)raw["courses"][0];raw["courses"]=new JArray(c);var r=(JObject)c["rooms"][0];c["rooms"]=new JArray(r);c["connections"]=new JArray();r["cols"]=30;r["rows"]=17;r["aiPolicy"]="inherit";r["phase"]="slow";r["environment"]="cold";r["entries"]=new JArray(new JObject{{"id","entry"},{"x",2},{"y",10},{"face",1}});r["exits"]=new JArray();r["movables"]=new JArray();r["zones"]=new JArray();var tiles=new JArray();for(int x=0;x<30;x++)tiles.Add(new JObject{{"x",x},{"y",12},{"collision",true}});r["tiles"]=tiles;r["objects"]=objects;c["rooms"]=new JArray(r);raw["courses"]=new JArray(c);return new NativeMotion(NativeProjectLoader.LoadBytes(Encoding.UTF8.GetBytes(raw.ToString()),"json",new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve}),rules:rules);}
            JObject Obj(string id,string type,int x,int y,bool collision=false,JObject parameters=null){return new JObject{{"id",id},{"type",type},{"x",x},{"y",y},{"w",1},{"h",1},{"collision",collision},{"params",parameters??new JObject()},{"trigger",new JObject{{"mode",type=="common.checkpoint"?"region":"foot"},{"requiresAI",false},{"distance",5},{"once",false},{"cooldown",1}}}};}
            foreach(bool side in new[]{false,true}){var game=Fixture(new JArray(Obj("rail","physics.rail",5,11,true,new JObject{{"sideTrigger",side},{"path",new JArray(new JObject{{"x",5.5},{"y",11.0}},new JObject{{"x",10.0},{"y",7.0}})}})));game.Player.x=136;game.Player.y=335;game.Tick(0);Check((game.Player.rail!=null)==side,"rail sideTrigger="+side);}
            var cpGame=Fixture(new JArray(Obj("cp","common.checkpoint",5,11,true)));cpGame.Player.x=164;cpGame.Player.y=324;cpGame.Player.grounded=true;cpGame.Tokens=17;cpGame.Tick(NativeMotion.Step);Check(cpGame.Checkpoint.id=="cp"&&cpGame.Checkpoint.y==324,"solid checkpoint top safe spawn");cpGame.Tokens=1;cpGame.Tick(NativeMotion.Step);Check(cpGame.Checkpoint.tokens==17,"same flag contact cannot overwrite snapshot");cpGame.Retry();Check(cpGame.Player.y==324&&cpGame.Tokens==17&&cpGame.RespawnRemaining==.5,"solid checkpoint restore resources");var frozen=cpGame.Player.x;cpGame.Tick(.03,new MotionInput{right=true,dashPressed=true});Check(cpGame.Player.x==frozen&&cpGame.Player.dashCount==0,"respawn input freeze");
            foreach(string policy in new[]{"preserve","life","checkpoint"}){var thermal=Obj("thermal","physics.thermal",5,11,true,new JObject{{"mode","toggle"},{"initialState","cold"}});thermal["resetPolicy"]=policy;var g=Fixture(new JArray(thermal,Obj("cp","common.checkpoint",9,11,false)));g.Player.x=164;g.Player.y=324;g.Player.grounded=true;g.Tick(NativeMotion.Step);Check(g.RoomEnvironment=="hot","thermal first contact "+policy);
                if(policy=="checkpoint"){g.Player.x=292;g.Player.y=356;g.Tick(0);Check(g.Checkpoint.id=="cp","checkpoint captures thermal snapshot");g.SetTemperature("","cold");}
                g.Retry();Check(g.RoomEnvironment==(policy=="life"?"cold":"hot"),"thermal resetPolicy "+policy);}
            var gate=Obj("gate","physics.jet",5,11,true,new JObject{{"launchX",100},{"launchY",-400}});gate["trigger"]["requiresAI"]=true;var gated=Fixture(new JArray(gate));gated.Player.x=164;gated.Player.y=324;gated.Player.grounded=true;gated.Tick(NativeMotion.Step);Check(gated.ObjectStates["gate"].waitingAI&&!gated.Player.launched,"requiresAI gates independent solid pad");gated.AI.active=true;gated.AI.id=gated.Room.AiId??gated.Course.AiId;gated.AI.x=176;gated.AI.y=350;gated.Tick(NativeMotion.Step);Check(gated.Player.launched&&gated.ObjectStates["gate"].hitAI,"AI distance enables pad and jet launches AI");
            var coins=new JArray();for(int i=0;i<5;i++)coins.Add(Obj("small"+i,"common.small",5+i,11));var latest=Fixture(coins,NativeGameplayRules.LatestPhysics);Check(latest.Charges==1&&latest.PaidStockCap==1,"latest paid stock starts at cap1");latest.Charges=0;for(int i=0;i<3;i++){latest.Player.x=(5+i)*32+4;latest.Player.y=356;latest.Tick(0);Check(latest.Charges==(i==2?1:0)&&latest.Recharge==(i==2?0:i+1),"three small recharge step "+i);}Check(latest.Tokens==3&&latest.Score==300,"latest small coin units and scores retained");latest.Player.x=260;latest.Tick(0);Check(latest.Recharge==0&&latest.Charges==1,"full stock does not bank extra recharge");latest.Charges=0;latest.Player.x=292;latest.Tick(0);Check(latest.Recharge==1&&latest.Charges==0,"after spend small recharge starts fresh");
            var big=Fixture(new JArray(Obj("big","common.coin",5,11)),NativeGameplayRules.LatestPhysics);big.Charges=0;big.Player.x=164;big.Player.y=356;big.Tick(0);Check(big.Charges==1&&big.Recharge==0&&big.Tokens==10&&big.Score==1000,"one large coin fills stock and preserves10 units");
            var manual=Fixture(new JArray(Obj("thermal","physics.thermal",5,11,true,new JObject{{"mode","toggle"}})),NativeGameplayRules.LatestPhysics);manual.Player.x=164;manual.Player.y=324;manual.Player.grounded=true;manual.Tick(NativeMotion.Step);Check(manual.RoomEnvironment=="cold"&&manual.NearbyInteraction?.Id=="thermal","latest temperature requires E and exposes prompt");manual.Tick(NativeMotion.Step,new MotionInput{interactPressed=true});Check(manual.RoomEnvironment=="hot","latest E changes temperature");manual.ObjectStates["thermal"].cooldown=0;manual.Tick(NativeMotion.Step);Check(manual.RoomEnvironment=="hot","latest hold does not retrigger without edge");manual.Tick(NativeMotion.Step,new MotionInput{interactPressed=true});Check(manual.RoomEnvironment=="cold","latest second E edge toggles again");
            var aiManual=Fixture(new JArray(Obj("start","common.aiStart",5,11,true)),NativeGameplayRules.LatestPhysics);aiManual.Player.x=164;aiManual.Player.y=324;aiManual.Player.grounded=true;aiManual.Tick(NativeMotion.Step);Check(!aiManual.AI.active,"latest AI foot contact alone does not start");aiManual.Tick(NativeMotion.Step,new MotionInput{interactPressed=true});Check(aiManual.AI.active,"latest AI starts on nearby E");
            var keys=new NativeKeyboardEvents();keys.Bind(10,MotionBinding.Interact);keys.Apply(10,true);keys.Apply(10,true);Check(keys.PendingEdges==1&&keys.TryRead(out var edge)&&edge.interactPressed&&!edge.WithoutEdges().interactPressed,"E repeat filtered and edge cleared");keys.Apply(10,false);keys.Apply(10,true);keys.DiscardEdges();Check(keys.PendingEdges==0,"pause/respawn E discard");
            var derived=NativePhysicsDemo.Derive(source);Check(derived.RoomCount==source.RoomCount&&derived.ConnectionCount==source.ConnectionCount&&derived.ObjectCount==source.ObjectCount,"latest derived project preserves topology and counts");foreach(var c in derived.Courses)foreach(var r in c.Rooms)foreach(var o in r.Objects)if(o.Type=="physics.ice")Check(o.Number("meltAfter")==1&&o.Number("respawnDelay")==3,"latest explicit ice1/3 "+o.Id);
            foreach(var rules in new[]{NativeGameplayRules.Editor255Compat,NativeGameplayRules.LatestPhysics}){var finalRoom=source.Courses[0].Rooms.Find(r=>r.Exits.Exists(e=>!source.Courses[0].Connections.Exists(c=>c.FromRoomId==r.Id&&c.ExitId==e.Id)));var finished=new NativeMotion(source,source.Courses[0].Id,finalRoom.Id,rules);var exit=finalRoom.Exits.Find(e=>!source.Courses[0].Connections.Exists(c=>c.FromRoomId==finalRoom.Id&&c.ExitId==e.Id));void ReachExit(){finished.SetDeveloperOptions(true,true,false);finished.Player.x=exit.X*32+4;finished.Player.y=exit.Y*32+4;finished.Player.vx=finished.Player.vy=0;finished.ExitCooldown=0;finished.Tick(0);}ReachExit();int awarded=finished.Score;Check(finished.Completed&&finished.Mode=="won"&&awarded>=50000,"first finish "+rules);finished.Mode="playing";ReachExit();Check(finished.Score==awarded&&finished.Mode=="won","core terminal award idempotent "+rules);finished.Retry();Check(!finished.Completed&&finished.Score==finished.Checkpoint.score&&finished.Score==0,"explicit retry rolls back pre-award checkpoint "+rules);finished.RespawnRemaining=0;ReachExit();Check(finished.Completed&&finished.Score==awarded,"retry can complete without stacking old award "+rules);}
            return checks;
        }
    }
}
